import java.math.BigDecimal;
import java.math.RoundingMode;

public class Main {
    public static void main(String[] args) {
        String[] pesanan = {"Nasi Goreng;2;25000", "Es Teh;2;5000"};
        BigDecimal subtotal = BigDecimal.ZERO;
        for (String p : pesanan) {
            String[] b = p.split(";");
            int qty = Integer.parseInt(b[1]);
            subtotal = subtotal.add(new BigDecimal(b[2]).multiply(new BigDecimal(qty)));
        }
        BigDecimal diskon = BigDecimal.ZERO;
        if (subtotal.compareTo(new BigDecimal("50000")) >= 0) {
            diskon = subtotal.multiply(new BigDecimal("0.10")).setScale(0, RoundingMode.HALF_UP);
        }
        System.out.println("Subtotal: " + subtotal);
        System.out.println("Diskon: " + diskon);
        System.out.println("Bayar: " + subtotal.subtract(diskon));
    }
}

